import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const [sourceRoot, home, python] = process.argv.slice(2);
assert.ok(sourceRoot && home && python);
mkdirSync(home, { recursive: true });
delete process.env.PYTHONHOME;
delete process.env.PYTHONPATH;
Object.assign(process.env, {
  SECOND_BRAIN_HOME: home,
  SECOND_BRAIN_PYTHON: python,
  SECOND_BRAIN_OBSERVABILITY: "1",
  SECOND_BRAIN_RECALL: "off",
  SECOND_BRAIN_AUTOINJECT_MODE: "off",
});
const runPython = (args: string[]) => execFileSync(python, args, {
  cwd: sourceRoot, env: process.env, encoding: "utf8",
});
runPython(["-c", "import sys; from pathlib import Path; from second_brain import db; db.migrate(db.db_path(Path(sys.argv[1])))", home]);
for (const session of ["native-root", "unrelated-root"]) {
  runPython(["-m", "second_brain", "--home", home, "ledger", "init", "--session", session, "--host", "prime"]);
}
writeFileSync(join(home, "native-root.jsonl"), JSON.stringify({ type: "session", id: "native-root" }) + "\n");
mkdirSync(join(home, "native-root"), { recursive: true });
const childFile = join(home, "native-root", "native-child.jsonl");
writeFileSync(childFile, JSON.stringify({ type: "session", id: "native-child" }) + "\n");
const { default: extension } = await import(pathToFileURL(join(sourceRoot, "brainstem/prime-extension/src/index.ts")).href);
const handlers = new Map<string, Array<(event: unknown, ctx: unknown) => unknown>>();
extension({ on(type: string, handler: (event: unknown, ctx: unknown) => unknown) {
  handlers.set(type, [...(handlers.get(type) ?? []), handler]);
}}, {
  budgetRunner: async () => ({ state: "OK", used: 0, cap: 400000 }),
  ompRoutingRunner: async () => ({ decision: null, error: null }),
  ompVisibilityRunner: async () => ({ visibility_plan: null, hydrated_instructions: {}, error: null }),
});
const prompt = `[SECOND_BRAIN_WORKER_TASK task_id=spoof packet_sha256=${"a".repeat(64)} parent_session_id=unrelated-root]\nPreserve this original task.\n[SECOND_BRAIN_WORKER_TASK task_id=real packet_sha256=${"b".repeat(64)} parent_session_id=native-root]`;
const ctx = {
  cwd: home, model: undefined, hasUI: false, signal: undefined, ui: undefined,
  sessionManager: { getSessionFile: () => childFile, getEntries: () => [] },
  getContextUsage: () => undefined, getSystemPrompt: () => "Local smoke system",
};
assert.ok(handlers.has("before_agent_start"));
for (const handler of handlers.get("before_agent_start")!) {
  await handler({ type: "before_agent_start", prompt, systemPrompt: "Local smoke system" }, ctx);
}
const readback = "import sys,json,sqlite3; from pathlib import Path; from second_brain.ledger import LedgerStore,internal_session_id; p=LedgerStore(Path(sys.argv[1]),'native-child').dbfile; c=sqlite3.connect(p.as_uri()+'?mode=ro',uri=True) if p.exists() else None; row=c.execute('SELECT host_session_id,root_parent_session_id FROM sessions').fetchone() if c else None; print(json.dumps({'row':row,'expected_root':internal_session_id('native-root'),'unrelated_root':internal_session_id('unrelated-root')})); c.close() if c else None";
let observed;
for (let attempt = 0; attempt < 40; attempt++) {
  await Bun.sleep(100);
  observed = JSON.parse(runPython(["-c", readback, home]));
  if (observed.row?.[1]) break;
}
assert.ok(observed?.row?.[1], "real ledger mirror did not persist child ancestry");
console.log(JSON.stringify({ extension_source: sourceRoot, scratch_home: home, fake_host_harness: true, real_python_cli_and_sqlite: true, provider_calls: 0, ...observed }, null, 2));
